const fs=require('fs');
const c=JSON.parse(fs.readFileSync('.lattice/story/actives/B-137a/checklist.json','utf8'));
const items=c.items||c;
let totalIntents=0, must=0;
for(const it of items){
  const vi=it.verificationIntent||{};
  const ev=it.verificationEvidence||[];
  console.log('=== '+it.id+' '+it.title+' status='+it.status);
  for(const col of ['happy','edge','adversarial']){
    for(const i of (vi[col]||[])){
      totalIntents++; if(i.priority==='must') must++;
      const matches=ev.filter(e=>e.intentRef===i.id||e.intentRef===it.id+':'+col+':'+((vi[col]||[]).indexOf(i)));
      console.log('  '+(i.id||it.id+':'+col+':'+(vi[col]||[]).indexOf(i))+' ['+i.priority+'/'+i.type+'] evidence='+matches.length+' -> '+matches.map(m=>m.kind+':'+m.result).join(','));
    }
  }
  console.log('  evidence entries total: '+ev.length);
}
console.log('TOTAL intents='+totalIntents+' must='+must);
